mapper.select:
SELECT COUNT(DISTINCT l.question_id)
FROM study_review_log l
WHERE l.user_id = #{userId}
  AND l.reviewed_at >= #{dayStart}
  AND NOT EXISTS (
      SELECT 1
      FROM study_review_log older
      WHERE older.user_id = l.user_id
        AND older.question_id = l.question_id
        AND older.reviewed_at < #{dayStart}
  )
